    5 => NSCellHighlighted,
    6 => NSCellLightsByContents,
    7 => NSCellLightsByGray,
    8 => NSChangeBackgroundCell,
    9 => NSCellLightsByBackground,
    10 => NSCellIsBordered,
    11 => NSCellHasOverlappingImage,
