mixin NSTokenFieldDelegateAdapter {
  /// Lazily creates a native adapter for this Dart implementation.
  late final NSTokenFieldDelegate asNSTokenFieldDelegate =
      NSTokenFieldDelegate$Builder.implementFrom(
        this as NSTokenFieldDelegateSpec,
      );
}

enum NSTokenStyle {
  NSTokenStyleDefault(0),
  NSTokenStyleNone(1),
  NSTokenStyleRounded(2),
  NSTokenStyleSquared(3),
  NSTokenStylePlainSquared(4);

  final int value;
  const NSTokenStyle(this.value);

  static NSTokenStyle fromValue(int value) => switch (value) {
    0 => NSTokenStyleDefault,
    1 => NSTokenStyleNone,
    2 => NSTokenStyleRounded,
    3 => NSTokenStyleSquared,
    4 => NSTokenStylePlainSquared,
    _ => throw ArgumentError('Unknown value for NSTokenStyle: $value'),
  };
}

extension NSToolTipOwner on objc.NSObject {
  objc.NSString view(
    NSView view, {
    required int stringForToolTip,
    required objc.CGPoint point,
    required ffi.Pointer<ffi.Void> userData,
